import{_ as o,o as a,c as t,a3 as r}from"./chunks/framework.BLaSdaBb.js";const g=JSON.parse('{"title":"Privacy Policy","description":"","frontmatter":{},"headers":[],"relativePath":"privacy.md","filePath":"privacy.md"}'),i={name:"privacy.md"};function s(n,e,d,l,h,c){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="privacy-policy" tabindex="-1">Privacy Policy <a class="header-anchor" href="#privacy-policy" aria-label="Permalink to &quot;Privacy Policy&quot;">​</a></h1><p><em>Last updated: 8 September 2026</em></p><p>Athanor is a single-player strategy game. It is built to need as little about you as possible, and most of it needs nothing at all: the game runs entirely on your own device unless you choose otherwise.</p><p>This policy covers the Android app, the browser version at <strong>play.athanor.games</strong>, and this guide at <strong>help.athanor.games</strong>.</p><h2 id="the-short-version" tabindex="-1">The short version <a class="header-anchor" href="#the-short-version" aria-label="Permalink to &quot;The short version&quot;">​</a></h2><ul><li>Your campaign is saved <strong>on your own device</strong>. It is only ever uploaded if you sign in and ask for a cloud save.</li><li>We do not sell your data, and we do not build a profile of you.</li><li>The game shows <strong>advertisements</strong>, supplied by Google. Those ads use cookies or a device advertising ID. You can turn personalised ads off, and on Android you can remove the banner entirely with a one-off purchase.</li><li>There are <strong>no accounts by default</strong>. Signing in is optional and exists only to carry a save between devices.</li></ul><h2 id="what-is-stored-on-your-device" tabindex="-1">What is stored on your device <a class="header-anchor" href="#what-is-stored-on-your-device" aria-label="Permalink to &quot;What is stored on your device&quot;">​</a></h2><p>The game keeps the following locally, using ordinary browser or app storage:</p><ul><li><strong>Your saved campaigns</strong>, including the world, your guild, and every unit in it.</li><li><strong>Your settings</strong>: sound, volume, fullscreen, auto-resolve, fog, and whether you have finished the walkthrough.</li><li><strong>What you have unlocked</strong> across campaigns, and whether you have purchased the removal of ads.</li></ul><p>None of this leaves your device on its own. Clearing your browser&#39;s site data, or uninstalling the app, removes all of it.</p><h2 id="cloud-saves-optional" tabindex="-1">Cloud saves (optional) <a class="header-anchor" href="#cloud-saves-optional" aria-label="Permalink to &quot;Cloud saves (optional)&quot;">​</a></h2><p>If you sign in, and only then, your saved campaign can be stored with Google Firebase so you can pick it up on another device. In that case we store your campaign data and the account identifier Google gives us. We never see your password. Sign out, and the game goes back to storing everything locally.</p><h2 id="crash-reports" tabindex="-1">Crash reports <a class="header-anchor" href="#crash-reports" aria-label="Permalink to &quot;Crash reports&quot;">​</a></h2><p>Where the app is built with crash reporting enabled, an unexpected failure sends Google Firebase Crashlytics a technical report: the error, where in the code it happened, and basic device information such as the model and operating system version. It does not include your saves or anything you have typed. Reports are used only to fix the game.</p><h2 id="advertising" tabindex="-1">Advertising <a class="header-anchor" href="#advertising" aria-label="Permalink to &quot;Advertising&quot;">​</a></h2><p>Athanor is free, and advertising is what pays for it.</p><ul><li><strong>In the browser</strong>, ads are served by <strong>Google AdSense</strong>.</li><li><strong>On this guide</strong>, a single unit below each page is served by the same <strong>Google AdSense</strong> account.</li><li><strong>On Android</strong>, a banner is served by <strong>Google AdMob</strong>.</li></ul><p>Google and its partners may use cookies, a device advertising identifier, and similar technologies to serve and measure ads. That includes, where you have agreed to it, ads chosen based on your previous activity. You can read how Google uses this information at <a href="https://policies.google.com/technologies/partner-sites" target="_blank" rel="noreferrer">policies.google.com/technologies/partner-sites</a>.</p><h3 id="your-choices" tabindex="-1">Your choices <a class="header-anchor" href="#your-choices" aria-label="Permalink to &quot;Your choices&quot;">​</a></h3><ul><li><strong>In the EEA, the UK and Switzerland</strong>, the game asks for your consent before requesting any ad, through Google&#39;s certified consent form. You may refuse, and you may change your answer at any time: open <strong>Settings → Ads &amp; Privacy → Privacy options</strong>.</li><li><strong>Anywhere</strong>, you can limit ad tracking through your device or browser settings: on Android, <em>Settings → Privacy → Ads</em>; in a browser, by blocking third-party cookies.</li><li><strong>On Android</strong>, a one-off in-app purchase removes the banner from the game for good on that device.</li></ul><p>We do not knowingly direct the game at children under 13, and we do not ask for or collect information from them.</p><h2 id="third-parties-we-rely-on" tabindex="-1">Third parties we rely on <a class="header-anchor" href="#third-parties-we-rely-on" aria-label="Permalink to &quot;Third parties we rely on&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Who</th><th>What for</th></tr></thead><tbody><tr><td>Google AdSense / AdMob</td><td>Serving the advertisements</td></tr><tr><td>Google Firebase</td><td>Optional sign-in and cloud saves</td></tr><tr><td>Google Firebase Crashlytics</td><td>Crash reports, where enabled</td></tr><tr><td>GitHub Pages</td><td>Hosting this guide and the browser version</td></tr><tr><td>Cloudflare</td><td>DNS and serving the site&#39;s <code>ads.txt</code></td></tr></tbody></table><p>Each of these handles data under its own privacy policy.</p><h2 id="your-rights" tabindex="-1">Your rights <a class="header-anchor" href="#your-rights" aria-label="Permalink to &quot;Your rights&quot;">​</a></h2><p>If you are in a region with data protection rights (the EEA, the UK, California and others), you may ask what is held about you, ask for it to be corrected, or ask for it to be deleted. In practice almost everything is already on your own device and under your control. For a cloud save, sign in and delete the save, or write to us and we will remove it.</p><h2 id="changes" tabindex="-1">Changes <a class="header-anchor" href="#changes" aria-label="Permalink to &quot;Changes&quot;">​</a></h2><p>If this policy changes in a way that matters, the date at the top of this page changes with it.</p><h2 id="contact" tabindex="-1">Contact <a class="header-anchor" href="#contact" aria-label="Permalink to &quot;Contact&quot;">​</a></h2><p>Questions about privacy, or a request about your data: <strong><a href="mailto:alex.rudolph.1987@gmail.com" target="_blank" rel="noreferrer">alex.rudolph.1987@gmail.com</a></strong></p>',30)])])}const p=o(i,[["render",s]]);export{g as __pageData,p as default};
